const items = $input.all();
if (!items || items.length === 0) {
  const wanted = $('Config').first().json['Topic Title'];
  throw new Error(`No topic found titled "${wanted}". It must exactly match a topic already created in Phase 1.`);
}
const topic = items[0].json;
return [{ json: { topic_id: topic.id, topic_title: topic.title, channel_id: topic.channel_id } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('No video at stage "rendered" found for this topic. Run Phase 4 (phase4-assembly.json), and Phase 4B (phase4b-render-poll.json) if it is still stuck at "render_requested", for this topic first.');
}
const video = items[0].json;
return [{ json: { id: video.id, channel_id: video.channel_id, script_id: video.script_id, render_url: video.render_url, duration_seconds: video.duration_seconds } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('No "final" script found for this topic — Phase 2 must have completed with a Critic pass.');
}
return [{ json: { script_content: items[0].json.content } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('No research dossier found for this topic — Phase 1 must have completed.');
}
const claims = Array.isArray(items[0].json.claims) ? items[0].json.claims : [];
return [{ json: { claims } }];

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('Channel not found for this topic — data inconsistency, check the topics/channels tables.');
}
const channel = items[0].json;
return [{ json: { name: channel.name, niche: channel.niche, brand_voice: channel.brand_voice, made_for_kids: !!channel.made_for_kids } }];

const items = $input.all();
const assets = items.map(i => i.json);
const missingLicenseCount = assets.filter(a => !a.license_note).length;
return [{ json: { assets, missing_license_count: missingLicenseCount } }];

const items = $input.all();
const priorAttempt = (items.length > 0 && items[0].json.attempt) ? items[0].json.attempt : 0;
return [{ json: { next_attempt: priorAttempt + 1 } }];

const claims = $('Pick Dossier Row').first().json.claims;
const scriptContent = $('Pick Script Row').first().json.script_content;
const channel = $('Pick Channel Info Row').first().json;
const video = $('Pick Video Row').first().json;
const assets = $('Pick Assets Rows').first().json.assets;
const missingLicenseCount = $('Pick Assets Rows').first().json.missing_license_count;
const attempt = $('Pick Prior QC Row').first().json.next_attempt;
const topicTitle = $('Pick Topic Row').first().json.topic_title;

const kidsClause = channel.made_for_kids
  ? '\n\nThis IS a made-for-kids channel. Additionally confirm: nothing in the content, imagery, or themes is inappropriate for young children, and there is no call to action that could read as soliciting children to click an external link or buy something. Report this as "kids_safety_pass": true|false.'
  : '\n\nThis is NOT a made-for-kids channel — skip the kids-safety check (report "kids_safety_pass": null).';

const system = `You are the Quality Control agent — the last gate before anything is marked ready
to publish. Standard: if a human editor would be embarrassed to publish this, it
fails. Be strict — a pass here is a claim you're staking the channel's credibility on.

Review against 5 categories. For each: PASS or FAIL, plus specific timestamped
notes for any fail.

1. FACTUAL — every stated claim matches the dossier's verified claims. No invented
   numbers, dates, or attributions.
2. VISUAL — footage matches narration, no distorted AI generation artifacts,
   correct flags/maps/logos, nothing that looks unlicensed.
3. AUDIO — narration is clear and natural-paced, no clipping, music doesn't compete
   with voice, no dead air.
4. EDITING — pacing holds attention, no visual repeated too long, captions (if
   present) are synced, hook lands within the first 15 seconds.
5. COPYRIGHT — no unlicensed music, no unlicensed footage, no reproduced
   copyrighted material (film clips, artwork, published text on screen).

overall_pass = true only if all 5 pass. For any failure, name the exact stage that
should receive the rework (research / script / visual director / asset sourcing /
voice / assembly) so it doesn't get routed to the wrong place.${kidsClause}

--- MATERIAL FOR THIS VIDEO ---

Topic: ${topicTitle}
Channel: ${channel.name} (niche: ${channel.niche})
Brand voice: ${channel.brand_voice}

Final script:
${scriptContent}

Research dossier claims (JSON):
${JSON.stringify(claims, null, 2)}

Assets used (JSON) — ${missingLicenseCount} of ${assets.length} are missing a license_note:
${JSON.stringify(assets, null, 2)}

Rendered video URL (open this yourself, or in a Claude session that can browse,
before judging VISUAL/AUDIO/EDITING — this prompt alone cannot show it to you):
${video.render_url}
Reported duration: ${video.duration_seconds ?? 'unknown'} seconds

This is QC attempt ${attempt} for this video.

--- RESPONSE FORMAT ---

Respond with JSON only, no prose outside the JSON, matching exactly this shape:
{
  "factual": { "pass": boolean, "notes": string },
  "visual": { "pass": boolean, "notes": string },
  "audio": { "pass": boolean, "notes": string },
  "editing": { "pass": boolean, "notes": string },
  "copyright": { "pass": boolean, "notes": string },
  "overall_pass": boolean,
  "rework_stage": "research" | "script" | "visual_director" | "asset_sourcing" | "voice" | "assembly" | null,
  "rework_reason": string | null,
  "kids_safety_pass": boolean | null
}`;

return [{ json: { system, attempt } }];

const raw = $input.first().json["Claude's QC JSON"] || '';
let parsed = null;
let parseError = null;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parseError = e.message;
}
const categories = ['factual', 'visual', 'audio', 'editing', 'copyright'];
const valid = parsed && categories.every(c => parsed[c] && typeof parsed[c].pass === 'boolean');
if (parseError || !valid) {
  throw new Error('Could not parse a valid QC JSON (needs factual/visual/audio/editing/copyright objects each with a boolean "pass"). Paste error: ' + (parseError || 'missing/malformed category'));
}

const missingLicenseCount = $('Pick Assets Rows').first().json.missing_license_count;
const attempt = $('Build QC Prompt').first().json.attempt;
const videoId = $('Pick Video Row').first().json.id;

// Hard rule, not trusted from the paste: any asset missing a license_note is an
// automatic copyright fail, per 05-PRODUCTION-HARDENING.md #8.
let copyrightPass = parsed.copyright.pass;
let copyrightNotes = parsed.copyright.notes;
if (missingLicenseCount > 0) {
  copyrightPass = false;
  copyrightNotes = `${copyrightNotes} [Enforced: ${missingLicenseCount} asset(s) on this video are missing a license_note — hard publish blocker regardless of the QC verdict.]`;
}

const kidsSafetyPass = typeof parsed.kids_safety_pass === 'boolean' ? parsed.kids_safety_pass : null;
const overallPass = parsed.factual.pass && parsed.visual.pass && parsed.audio.pass && parsed.editing.pass && copyrightPass && (kidsSafetyPass === null || kidsSafetyPass === true);

return [{ json: {
  video_id: videoId,
  attempt,
  factual_pass: parsed.factual.pass,
  visual_pass: parsed.visual.pass,
  audio_pass: parsed.audio.pass,
  editing_pass: parsed.editing.pass,
  copyright_pass: copyrightPass,
  overall_pass: overallPass,
  notes: {
    factual: parsed.factual.notes,
    visual: parsed.visual.notes,
    audio: parsed.audio.notes,
    editing: parsed.editing.notes,
    copyright: copyrightNotes,
    rework_stage: parsed.rework_stage || null,
    rework_reason: parsed.rework_reason || null,
    kids_safety_pass: kidsSafetyPass,
    missing_license_count: missingLicenseCount
  }
} }];

const qc = $('Parse QC JSON').first().json;
let result;
if (qc.overall_pass) {
  result = `QC PASSED (attempt ${qc.attempt}) — videos.stage set to "qc_passed".`;
} else if (qc.attempt >= 3) {
  result = `QC FAILED for the 3rd time — videos.status set to "needs_human". Rework stage: ${qc.notes.rework_stage || 'unspecified'}. Reason: ${qc.notes.rework_reason || 'see notes'}`;
} else {
  result = `QC FAILED (attempt ${qc.attempt}/3) — video left at stage "rendered", nothing auto-looped. Rework stage: ${qc.notes.rework_stage || 'unspecified'}. Reason: ${qc.notes.rework_reason || 'see notes'}. Fix it, then re-submit this form.`;
}
return [{ json: {
  result,
  topic: $('Pick Topic Row').first().json.topic_title,
  video_id: qc.video_id,
  overall_pass: qc.overall_pass,
  attempt: qc.attempt,
  notes: qc.notes
} }];
